import java.math.BigDecimal;
import java.math.RoundingMode;

public final class OrderTotal {
    private static final BigDecimal MAX = new BigDecimal("9999999.99");

    private OrderTotal() {}

    public static BigDecimal calculate(BigDecimal subtotal, BigDecimal tax) {
        BigDecimal total = subtotal.setScale(2, RoundingMode.HALF_UP)
                .add(tax.setScale(2, RoundingMode.HALF_UP));
        if (total.compareTo(MAX) > 0) total = MAX;
        return total.setScale(2, RoundingMode.HALF_UP);
    }
}
